import os
import base64
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _to_dict(obj: Any) -> Any:
    if obj is None:
        return None
    if isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, list):
        return [_to_dict(item) for item in obj]
    if isinstance(obj, dict):
        return {k: _to_dict(v) for k, v in obj.items()}
    if hasattr(obj, "to_dict"):
        try:
            return _to_dict(obj.to_dict())
        except Exception:
            pass
    if hasattr(obj, "__dict__"):
        return {k: _to_dict(v) for k, v in obj.__dict__.items() if not k.startswith("_")}
    return str(obj)


def _extract_field_content(fields: Dict[str, Any], *names: str) -> Optional[str]:
    for name in names:
        field = fields.get(name)
        if field is None:
            continue
        if isinstance(field, dict):
            for key in ("content", "value", "text"):
                if field.get(key) not in (None, ""):
                    return str(field[key])
            value_type = field.get("value_type")
            if value_type == "date" and field.get("valueDate"):
                return str(field["valueDate"])
            if value_type == "currency" and field.get("valueCurrency"):
                cur = field["valueCurrency"]
                if isinstance(cur, dict):
                    amount = cur.get("amount")
                    code = cur.get("currencyCode")
                    if amount is not None and code:
                        return f"{amount} {code}"
                    if amount is not None:
                        return str(amount)
        elif hasattr(field, "content") and getattr(field, "content"):
            return str(getattr(field, "content"))
        elif hasattr(field, "value"):
            val = getattr(field, "value")
            if val is not None:
                return str(val)
    return None


def _extract_invoice_result(result: Any) -> Dict[str, Any]:
    result_dict = _to_dict(result)
    documents = result_dict.get("documents") or []
    invoice_doc = documents[0] if documents else {}

    fields = invoice_doc.get("fields") or {}
    vendor = _extract_field_content(
        fields,
        "VendorName",
        "vendorName",
        "MerchantName",
        "SellerName",
        "CustomerName",
    )
    date = _extract_field_content(
        fields,
        "InvoiceDate",
        "invoiceDate",
        "TransactionDate",
        "DueDate",
    )
    total = _extract_field_content(
        fields,
        "InvoiceTotal",
        "invoiceTotal",
        "AmountDue",
        "Total",
        "grandTotal",
    )

    line_items: List[Dict[str, Any]] = []
    for key in ("Items", "LineItems", "lineItems"):
        items_field = fields.get(key)
        if not items_field:
            continue
        if isinstance(items_field, dict):
            items_value = items_field.get("valueArray") or items_field.get("items") or []
        else:
            items_value = getattr(items_field, "value_array", None) or getattr(items_field, "items", None) or []
        for item in items_value:
            item_dict = _to_dict(item)
            item_fields = item_dict.get("valueObject") or item_dict.get("fields") or item_dict
            description = _extract_field_content(item_fields, "Description", "Item", "Name", "ProductCode")
            quantity = _extract_field_content(item_fields, "Quantity", "qty")
            unit_price = _extract_field_content(item_fields, "UnitPrice", "Unit Cost", "Price")
            amount = _extract_field_content(item_fields, "Amount", "TotalPrice", "LineTotal", "Total")
            line_items.append(
                {
                    "description": description,
                    "quantity": quantity,
                    "unit_price": unit_price,
                    "amount": amount,
                    "raw": item_dict,
                }
            )
        break

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw": result_dict,
    }


def extract_invoice_fields(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        analyze_request=document_bytes,
        content_type=content_type,
    )
    result = poller.result()
    return _extract_invoice_result(result)


def extract_invoice_fields_from_file(file_path: str, content_type: str = "application/pdf") -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        return extract_invoice_fields(f.read(), content_type=content_type)
